#!/usr/bin/env python3
"""enzyme/catalytic-site-annotator — auto-generated run.py (archetype=msa_conservation).

第一版只实现 simulate 模式:从 stdin/args 拿 inputs,产合理合成数据 JSON。
真实现路径(simulate=False)留 stub:返回 not-implemented + 提示。

输入契约:
  stdin JSON,字段按 SKILL.md 的 inputs 段;simulate 默认 true。
  CLI 兜底:--simulate / 各位置参数。

输出:
  stdout JSON;失败时也写 JSON {"ok": false, "error": "..."} 而非裸 traceback。
"""
import json
import sys

ARCHETYPE = "msa_conservation"
BRAIN = "enzyme"
SKILL = "catalytic-site-annotator"

def simulate(payload):
    """auto-generated by regen_simulate.py — outputs schema 来自 SKILL.md."""
    import copy
    import random
    random.seed(int(payload.get("seed", 42)) if isinstance(payload, dict) else 42)
    out = copy.deepcopy({'skill_id': 'catalytic-site-annotator', 'msa_path': '', 'n_sequences': 0, 'conservation_csv': '', 'diagnostics': {'brain': 'enzyme', 'archetype': 'msa_conservation'}})
    if isinstance(out, dict):
        out.setdefault("diagnostics", {})
        if isinstance(out["diagnostics"], dict):
            out["diagnostics"].update({
                "simulated": True,
                "archetype": ARCHETYPE,
                "brain": BRAIN,
                "skill": SKILL,
            })
        if "skill_id" in out and not out["skill_id"]:
            out["skill_id"] = SKILL
    return out

def real(payload):
    """Catalytic site 注释:用 M-CSA / PDBe-KB REST API 查 PDB ID 对应的 catalytic residues。"""
    import os as _os
    import tempfile as _tempfile
    import time as _time
    try:
        from brains._common.lib.run_tool import run_tool
    except ImportError:
        import sys as _sys
        _sys.path.insert(0, "/home/zkyd/data1/mzy/praxis2-brains")
        from _common.lib.run_tool import run_tool  # noqa: F401
    pdb_id = payload.get("pdb_id") or payload.get("pdb")
    diagnostics = {"brain": BRAIN, "skill": SKILL, "archetype": ARCHETYPE,
                   "source": "M-CSA / PDBe-KB REST"}
    if _os.environ.get("PRAXIS_SKILL_DRY_HOST") == "1":
        return {"ok": True, "skill_id": SKILL, "msa_path": "", "n_sequences": 0,
                "conservation_csv": "", "diagnostics": {**diagnostics, "dry": True}}
    if not pdb_id:
        return {"ok": False, "error": "需要 pdb_id", "diagnostics": diagnostics}
    script = (
        "import json, sys, urllib.request\n"
        f"pdb = {pdb_id!r}.lower()\n"
        "results = {}\n"
        "# PDBe-KB residue-level annotations\n"
        "try:\n"
        "    url = f'https://www.ebi.ac.uk/pdbe/graph-api/uniprot/active_site/{pdb}'\n"
        "    with urllib.request.urlopen(url, timeout=20) as r:\n"
        "        data = json.loads(r.read())\n"
        "    active_residues = []\n"
        "    for u, recs in data.items():\n"
        "        for rec in recs:\n"
        "            for site in rec.get('data', []):\n"
        "                active_residues.append({'uniprot': u, 'residue_number': site.get('start', {}).get('residue_number'),\n"
        "                                        'description': site.get('description')})\n"
        "    results['n_catalytic_residues'] = len(active_residues)\n"
        "    results['residues'] = active_residues[:50]\n"
        "except Exception as e:\n"
        "    results['__err'] = repr(e)[:200]\n"
        "json.dump(results, sys.stdout)\n"
    )
    t0 = _time.time()
    r = run_tool(["python3", "-c", script], timeout=60)
    diagnostics["subprocess"] = {"wall_sec": r.get("wall_sec"), "rc": r.get("returncode")}
    if not r["ok"]:
        return {"ok": False, "error": r.get("error", "catalytic-site fetch 失败"),
                "diagnostics": diagnostics}
    try:
        parsed = json.loads(r["stdout"])
    except json.JSONDecodeError as e:
        return {"ok": False, "error": f"stdout 解析失败: {e}", "diagnostics": diagnostics}
    return {"ok": True, "skill_id": SKILL,
            "msa_path": "", "conservation_csv": "",
            "n_sequences": parsed.get("n_catalytic_residues", 0),
            "runtime_sec": round(_time.time() - t0, 2),
            "diagnostics": {**diagnostics, **parsed}}

def main():
    # stdin 优先(SkillExecTool 走 stdin)
    payload = {}
    if not sys.stdin.isatty():
        try:
            payload = json.load(sys.stdin)
            if not isinstance(payload, dict):
                payload = {}
        except json.JSONDecodeError:
            payload = {}
    if not payload:
        # 简易 CLI 兜底
        import argparse
        ap = argparse.ArgumentParser()
        ap.add_argument("--simulate", action="store_true", default=True)
        ap.add_argument("--seed", type=int, default=42)
        args, _ = ap.parse_known_args()
        payload = {"simulate": args.simulate, "seed": args.seed}

    simulate_mode = bool(payload.get("simulate", True))
    try:
        out = simulate(payload) if simulate_mode else real(payload)
    except Exception as e:
        out = {"ok": False, "error": f"run.py 内部错误: {e!r}"}

    if isinstance(out, dict):
        out.setdefault("diagnostics", {})
        if isinstance(out["diagnostics"], dict):
            out["diagnostics"].update({"archetype": ARCHETYPE, "brain": BRAIN, "skill": SKILL})
    json.dump(out, sys.stdout, ensure_ascii=False)
    sys.stdout.write("\n")
    return 0

if __name__ == "__main__":
    sys.exit(main())
